"""AiDOOS branding for the report + form.

The logo is embedded as a data URI so the report stays self-contained (no external image).
LOGO_DATA_URI is filled from the real AiDOOS asset via packaging/embed_logo.py -- until
that's set we render NO logo (text wordmark only) rather than a wrong recreation.

The "Scope with AiDOOS" link routes to the AiDOOS problem-statement box, pre-filled with
the opportunity as the initiative text (like selecting a sample problem on aidoos.com).
Set AIDOOS_URL / SCOPE_PATH / SCOPE_PARAM to the real values.
"""

from __future__ import annotations

from urllib.parse import urlencode

# --- logo (data URI) -------------------------------------------------------------------
# Set by packaging/embed_logo.py from the real AiDOOS logo file. Empty = text-only brand.
LOGO_DATA_URI = "data:image/png;base64,"

# --- AiDOOS conversion link ------------------------------------------------------------
AIDOOS_URL = "https://aidoos.com"     # base site (no 404)
SCOPE_PATH = "/proposal"               # land on the proposal intake, NOT the homepage - the
                                       # customer already gave the input by clicking "Build";
                                       # the SPA reads `?prompt=` and skips straight in
SCOPE_PARAM = "prompt"                 # the query param that pre-fills the box


def logo(css_class: str = "brand") -> str:
    if not LOGO_DATA_URI:
        return ""
    return f'<img class="{css_class}" src="{LOGO_DATA_URI}" alt="AiDOOS">'


def favicon() -> str:
    """A <link rel=icon> using the embedded logo (inline data URI, no external fetch)."""
    if not LOGO_DATA_URI:
        return ""
    return f'<link rel="icon" href="{LOGO_DATA_URI}">'


def scope_url(prompt: str) -> str:
    """Build the AiDOOS link that opens the problem-statement box pre-filled with `prompt`."""
    query = urlencode({SCOPE_PARAM: prompt, "from": "stackxray"})
    return f"{AIDOOS_URL}{SCOPE_PATH}?{query}"
